function readStoredZip(buffer) {
  const entries = new Map(); let offset = 0;
  while (buffer.readUInt32LE(offset) === 0x04034b50) {
    const method = buffer.readUInt16LE(offset + 8), size = buffer.readUInt32LE(offset + 18), nameLength = buffer.readUInt16LE(offset + 26), extraLength = buffer.readUInt16LE(offset + 28);
    assert.equal(method, 0, 'current ZIP uses standard store mode');
    const nameStart = offset + 30, name = buffer.subarray(nameStart, nameStart + nameLength).toString('utf8'), dataStart = nameStart + nameLength + extraLength;
    entries.set(name, buffer.subarray(dataStart, dataStart + size)); offset = dataStart + size;
  }
  return entries;
}

